20	export async function updatePreferences(patch: unknown): Promise<void> {
21	  const data = PreferencesSchema.partial().parse(patch);
22	
23	  const supabase = await createClient();
24	  const {
25	    data: { user },
26	  } = await supabase.auth.getUser();
27	  if (!user) throw new Error("Not signed in");
28	
29	  const { data: row } = await supabase
30	    .from("profiles")
31	    .select("preferences")
32	    .eq("id", user.id)
33	    .single();
34	
35	  const next = { ...readPreferences(row?.preferences), ...data };
36	
37	  const { error } = await supabase.from("profiles").update({ preferences: next }).eq("id", user.id);
38	  if (error) throw new Error(error.message);
