107	/**
108	 * Today's looks were composed for the OLD city's weather, so a move invalidates
109	 * them. Decision 5 caches the drop; it does not make it correct for a different
110	 * climate — without this you land in Reykjavik and see outfits built for 26°C
111	 * Manila rain under a strip reading 12°C overcast.
112	 *
113	 * The rebuild is FREE, and that is not incidental: `generation_events` records
114	 * `kind` by whether a stored set already exists, so deleting the set is exactly
115	 * what makes the next call a `drop`. MONETISATION §2 — drops are never metered,
116	 * on any tier. The user changed a setting; they did not ask for a reroll.
117	 *
118	 * ⚠️ Keyed on the NEW timezone. Crossing zones can change what "today" is, and
119	 * deleting under the old key would destroy a past day's history while leaving
120	 * the row that is actually stale untouched — both intentions inverted.
121	 */
122	async function clearTodaysDrop(
123	  supabase: Awaited<ReturnType<typeof createClient>>,
124	  userId: string,
125	  timezone: string,
126	): Promise<void> {
127	  const today = localDateFor(new Date(), timezone);
128	
129	  // Styled looks carry a weather snapshot too, and are cached per
130	  // (user, item, local day) — a look styled for Manila is as wrong as a drop is.
131	  const { data: rows } = await supabase
132	    .from("outfits")
133	    .select("id")
134	    .eq("user_id", userId)
135	    .eq("generated_on", today);
136	
137	  const ids = (rows ?? []).map((r) => r.id);
138	  if (!ids.length) return;
139	
140	  await supabase.from("outfit_items").delete().in("outfit_id", ids);
141	  await supabase.from("outfits").delete().in("id", ids);
142	}
