98	export function locationChanged(
99	  next: { lat: number; lon: number },
100	  // Only the coordinates are read, so only those are required — callers that
101	  // select a narrow column set should not have to fetch a label they ignore.
102	  profile?: Pick<ProfileLocation, "location_lat" | "location_lon"> | null,
