13	/**
14	 * Everything the Stylist's weather pill and the Settings location row share:
15	 * city search, an explicit "use my location" tap, and the three pieces of state
16	 * the UI needs to be honest about what is happening.
17	 *
18	 * ⚠️ It deliberately does NOT own the Stylist's silent GPS refresh on load.
19	 * That exists because the Stylist generates on mount and wants a fresh fix;
20	 * Settings has no equivalent moment and must not rewrite a location while the
21	 * user is looking at it. It also gates itself on `res.weather.locationOrigin`
22	 * from a generate result, which Settings does not have. If a later plan unifies
23	 * it, pass the stored origin IN as an argument (Settings can read
24	 * `location_source` server-side) rather than re-deriving it here.
25	 */
26	export function useLocationPicker(opts?: { onPick?: (p: PickedLocation) => void }) {
27	  const onPick = opts?.onPick;
28	
29	  const [cities, setCities] = useState<City[]>([]);
30	  const [locating, setLocating] = useState(false);
31	  const [geoError, setGeoError] = useState<string | null>(null);
32	  // Optimistic: the row shows until we learn the browser has no geolocation at
33	  // all, at which point it disappears and city search is the only path. A
34	  // DENIED permission is not the same thing — that is recoverable in system
35	  // settings, so the control stays and explains itself on tap.
36	  const [geoSupported, setGeoSupported] = useState(true);
37	
38	  useEffect(() => {
39	    let cancelled = false;
40	    // Querying permission never prompts; reading the position would. So this
41	    // only ever learns whether the API exists.
42	    permissionState().then((state) => {
43	      if (!cancelled && state === "unsupported") setGeoSupported(false);
44	    });
45	    return () => {
46	      cancelled = true;
47	    };
48	  }, []);
49	
50	  const search = useCallback((q: string) => {
51	    // The input fires on every keystroke, and a single letter matches most of
52	    // the planet. Two characters is the floor that makes the result list mean
53	    // anything.
54	    if (q.trim().length < 2) return;
55	    searchCities(q).then(setCities).catch(() => setCities([]));
56	  }, []);
57	
58	  const useMyLocation = useCallback(() => {
59	    setLocating(true);
60	    setGeoError(null);
61	    getCurrentPosition()
62	      .then((c) =>
63	        // Never reverse-geocoded: Open-Meteo has no reverse endpoint (D8) and a
64	        // third-party one would ship precise user coordinates off-stack.
65	        onPick?.({ ...c, label: "Current location", source: "geo" }),
66	      )
67	      .catch((e) =>
68	        setGeoError(e instanceof GeoError && e.kind === "denied" ? DENIED_COPY : FAILED_COPY),
69	      )
70	      .finally(() => setLocating(false));
71	  }, [onPick]);
72	
73	  return { cities, search, useMyLocation, locating, geoError, geoSupported };
74	}
